export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function quote(step: QuoteStep): number {
  const base = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  return Math.ceil(base * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
}
EOF
